import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // 1. DESIGN TOKENS & SYSTEM PALETTE
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const inkColor = new THREE.Color(colors.ink);
  const paperColor = new THREE.Color(colors.paper);
  const accentColor = new THREE.Color(colors.accent);
  const surfaceColor = new THREE.Color(colors.surface);

  // Keep track of resources to clean up
  const timelines = [];
  const resourcesToDispose = [];

  // 2. BACKGROUND STAGE (Avoid Flat Void)
  const bgGeo = new THREE.PlaneGeometry(8, 6);
  resourcesToDispose.push(bgGeo);

  // Gradient backdrop shader node material
  const bgMat = new MeshBasicNodeMaterial();
  const vUv = uv();
  // Create solid dark metallic vertical gradient with accent red glow at base
  const gradientFactor = vUv.y;
  const gradientColor = mix(
    vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
    vec3(inkColor.r, inkColor.g, inkColor.b),
    gradientFactor
  );
  // Add subtle red accent glow at the bottom edge
  const glowFactor = smoothstep(0.0, 0.4, uniform(1.0).sub(vUv.y));
  const finalBgColor = mix(
    gradientColor,
    vec3(accentColor.r * 0.15, accentColor.g * 0.15, accentColor.b * 0.15),
    glowFactor
  );

  bgMat.colorNode = finalBgColor;
  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.z = -2.5;
  group.add(bgMesh);

  // 3. MAIN SUBJECT: PARALLAX DEPTH PLANE
  // 64x64 segments for smooth displacement mapping
  const planeGeo = new PlaneGeometry(4.5, 2.8, 64, 64);
  resourcesToDispose.push(planeGeo);

  // Create customized basic node material for high-performance depth displacement
  const contentMat = new MeshBasicNodeMaterial();
  resourcesToDispose.push(contentMat);

  // Uniform inputs for interactive depth displacement offset
  const uDepthOffset = uniform(0.0);
  const uMouseOffset = uniform(new THREE.Vector2(0, 0));

  // Load physical texture maps
  ctx.textureLoader.loadTexture(config.imageUrl ?? '/prism-mock/home/nodes/parallax-stack.png')
    .then((colorTex) => {
      contentMat.colorNode = texture(colorTex, uv());
      contentMat.needsUpdate = true;
    });

  ctx.textureLoader.loadTexture(config.depthMapUrl ?? '/prism-mock/home/nodes/parallax-stack.depth.png')
    .then((depthTex) => {
      // Offset texture coordinates using target depth map to create parallax illusion
      const depthVal = texture(depthTex, uv()).r;
      const displacedUv = uv().add(uMouseOffset.mul(depthVal).mul(0.08));

      // Update color node mapping with displaced uv
      ctx.textureLoader.loadTexture(config.imageUrl ?? '/prism-mock/home/nodes/parallax-stack.png')
        .then((colorTex) => {
          contentMat.colorNode = texture(colorTex, displacedUv);
          contentMat.needsUpdate = true;
        });

      // Apply physical mesh vertex displacement along normal vector
      contentMat.positionNode = positionLocal.add(normalLocal.mul(depthVal.mul(uDepthOffset).mul(0.35)));
      contentMat.needsUpdate = true;
    });

  const subjectMesh = new THREE.Mesh(planeGeo, contentMat);
  group.add(subjectMesh);

  // 4. INTERACTION LAYERS & TEXT LABELS
  const labelGroup = new THREE.Group();
  labelGroup.position.set(0, 0, 0.1);
  group.add(labelGroup);

  // Display Title: Pricing list item
  const titleText = ctx.fontAtlas.createText('CHRONOGRAPH ATELIER I', {
    fontSize: 0.22,
    color: colors.paper,
    align: 'left'
  });
  titleText.position.set(-2.0, 0.4, 0.05);
  labelGroup.add(titleText);

  // Meta info mono label
  const metaText = ctx.fontAtlas.createText('CAL. 1883 / INK SHIELD', {
    fontSize: 0.1,
    color: colors.accent,
    align: 'left'
  });
  metaText.position.set(-2.0, 0.1, 0.05);
  labelGroup.add(metaText);

  // Price Display
  const priceText = ctx.fontAtlas.createText('EUR 9,800', {
    fontSize: 0.18,
    color: colors.paper,
    align: 'right'
  });
  priceText.position.set(2.0, 0.3, 0.05);
  labelGroup.add(priceText);

  // Subtle Machined Divider Line
  const lineGeo = new PlaneGeometry(4.0, 0.015, 1, 1);
  resourcesToDispose.push(lineGeo);
  const lineMat = new MeshBasicNodeMaterial();
  lineMat.colorNode = vec3(accentColor.r * 0.4, accentColor.g * 0.4, accentColor.b * 0.4);
  const dividerLine = new THREE.Mesh(lineGeo, lineMat);
  dividerLine.position.set(0, -0.6, 0.02);
  labelGroup.add(dividerLine);

  // Contact Shadow Plane at base
  const shadowGeo = new PlaneGeometry(4.5, 0.5);
  resourcesToDispose.push(shadowGeo);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = uniform(0.5);
  shadowMat.transparent = true;
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2.2;
  shadowMesh.position.set(0, -1.5, -0.2);
  group.add(shadowMesh);

  // Accent local lights for cinematic mood
  const rimLight = new THREE.DirectionalLight(colors.accent, 1.2);
  rimLight.position.set(3, -2, 2);
  group.add(rimLight);

  // 5. ENTRANCE ANIMATION (Weighted Settle)
  group.position.y += 0.5;
  group.scale.set(0.95, 0.95, 0.95);

  const entranceTl = gsap.timeline({ defaults: { ease: 'power4.out' } });
  entranceTl.to(group.position, { y: 0, duration: 1.1 }, 0);
  entranceTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 1.1 }, 0);
  timelines.push(entranceTl);

  // 6. EVENT HANDLING & INTERACTIVE BEHAVIOR
  let mouseMoveHandler = null;

  group.userData.handlers = {
    pointerover: () => {
      // Preset subtle rise-in and displacement depth push on hover
      gsap.to(subjectMesh.position, { z: 0.15, duration: 0.4, ease: 'power2.out' });
      gsap.to(uDepthOffset, { value: 1.0, duration: 0.6, ease: 'power2.out' });
    },
    pointerout: () => {
      gsap.to(subjectMesh.position, { z: 0, duration: 0.4, ease: 'power2.out' });
      gsap.to(uDepthOffset, { value: 0.0, duration: 0.6, ease: 'power2.out' });
      gsap.to(uMouseOffset.value, { x: 0, y: 0, duration: 0.8, ease: 'power2.out' });
    },
    pointermove: (event) => {
      // Dynamic pointer tracking for raw depth-offset calculations
      if (event.intersection) {
        const u = event.intersection.uv.x - 0.5;
        const v = event.intersection.uv.y - 0.5;
        gsap.to(uMouseOffset.value, { x: u, y: v, duration: 0.3, ease: 'power1.out' });
      }
    },
    click: () => {
      // Trigger checkout begin mutation / pricing selection
      ctx.emit('hub-pricing.select', { itemId: 'chronograph-atelier-1' });

      // Elastic click recoil
      const clickTl = gsap.timeline();
      clickTl.to(subjectMesh.scale, { x: 0.97, y: 0.97, duration: 0.1, ease: 'power2.out' });
      clickTl.to(subjectMesh.scale, { x: 1.0, y: 1.0, duration: 0.4, ease: 'back.out(2)' });
      timelines.push(clickTl);
    }
  };

  // 7. CINEMATIC PRIMITIVES APPLICATION
  const appliedPrimitives = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        const inst = ctx.primitives[prim.name](group, prim.params);
        if (inst) appliedPrimitives.push(inst);
      }
    }
  }

  // 8. UNMOUNT & DISPOSAL CLEANUP
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    appliedPrimitives.forEach((p) => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });
    resourcesToDispose.forEach((resource) => {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    });
  };

  return group;
}
